#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>

typedef struct Node {
    struct Node* next[26];
    bool end;
} Node;

static Node* newNode(void) {
    return (Node*)calloc(1, sizeof(Node));
}

char** findAllConcatenatedWordsInADict(char** words, int wordsSize, int* returnSize) {
    Node* root = newNode();
    for (int i=0;i<wordsSize;i++) {
        Node* p=root;
        for (int j=0; words[i][j]; j++) {
            int k=words[i][j]-'a';
            if (!p->next[k]) p->next[k]=newNode();
            p=p->next[k];
        }
        p->end=true;
    }

    char** ans=(char**)malloc(wordsSize*sizeof(char*));
    *returnSize=0;
    for(int w=0;w<wordsSize;w++){
        int n=(int)strlen(words[w]);
        bool* dp=(bool*)calloc(n+1,sizeof(bool));
        dp[0]=true;
        for(int i=0;i<n;i++){
            if(!dp[i]) continue;
            Node* p=root;
            for(int j=i;j<n;j++){
                p=p->next[words[w][j]-'a'];
                if(!p) break;
                if(p->end && j+1-i<n) dp[j+1]=true;
            }
        }
        if(dp[n]) {
            size_t z=strlen(words[w]);
            ans[*returnSize]=(char*)malloc(z+1);
            memcpy(ans[*returnSize],words[w],z+1);
            (*returnSize)++;
        }
        free(dp);
    }
    return ans;
}

