class Solution {
    static class Node {
        Map<Character, Node> next = new HashMap<>();
        boolean end;
    }

    public List<String> findAllConcatenatedWordsInADict(String[] words) {
        Node root = new Node();
        for (String word : words) {
            Node node = root;
            for (int i = 0; i < word.length(); i++)
                node = node.next.computeIfAbsent(word.charAt(i), k -> new Node());
            node.end = true;
        }

        List<String> result = new ArrayList<>();
        for (String word : words) {
            int n = word.length();
            boolean[] dp = new boolean[n + 1];
            dp[0] = true;
            for (int i = 0; i < n; i++) {
                if (!dp[i]) continue;
                Node node = root;
                for (int j = i; j < n; j++) {
                    node = node.next.get(word.charAt(j));
                    if (node == null) break;
                    if (node.end && j + 1 - i < n) dp[j + 1] = true;
                }
            }
            if (dp[n]) result.add(word);
        }
        return result;
    }
}

