from typing import List

class Solution:
    def findAllConcatenatedWordsInADict(self, words: List[str]) -> List[str]:
        class Node:
            __slots__ = ("next", "end")
            def __init__(self):
                self.next = {}
                self.end = False

        root = Node()
        for word in words:
            node = root
            for ch in word:
                node = node.next.setdefault(ch, Node())
            node.end = True

        result = []
        for word in words:
            n = len(word)
            dp = [False] * (n + 1)
            dp[0] = True
            for i in range(n):
                if not dp[i]:
                    continue
                node = root
                for j in range(i, n):
                    node = node.next.get(word[j])
                    if node is None:
                        break
                    if node.end and j + 1 - i < n:
                        dp[j + 1] = True
            if dp[n]:
                result.append(word)
        return result

