public class Main {
    public static void main(String[] args) throws Exception {
        String input = new String(System.in.readAllBytes()).trim();
        List<String> words = parseWords(input);
        List<String> result = new Solution().findAllConcatenatedWordsInADict(words.toArray(new String[0]));
        StringBuilder out = new StringBuilder("[");
        for (int i = 0; i < result.size(); i++) {
            if (i > 0) out.append(',');
            out.append('"').append(result.get(i)).append('"');
        }
        out.append(']');
        System.out.print(out);
    }

    static List<String> parseWords(String s) {
        List<String> words = new ArrayList<>();
        boolean inString = false;
        StringBuilder cur = new StringBuilder();
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (c == '"') {
                if (inString) { words.add(cur.toString()); cur.setLength(0); }
                inString = !inString;
            } else if (inString) cur.append(c);
        }
        return words;
    }
}

